window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-584d2e8102693d79"]={"versions": [{"id": "FIG-584d2e8102693d79", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm (<code>Component Model</code>) zur Einordnung der Speichermodule in die AUTOSAR-Basissoftwarearchitektur. Das Diagramm zeigt die Schichtenstruktur des Speichersubsystems (Memory Stack) bestehend aus den drei Paketen bzw. Modulschichten <code>NVRAM Manager</code> (Services Layer), <code>Memory Hardware Abstraction</code> (ECU Abstraction Layer) und <code>Memory Drivers</code> (Microcontroller Abstraction Layer / MCAL bzw. Complex Drivers).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in drei Hauptpakete:</p>\n<ul class=\"fig-list\">\n<li><strong>NVRAM Manager</strong>: Übergeordnete Service-Komponente zur Verwaltung nichtflüchtiger Daten.</li>\n<li><strong>Memory Hardware Abstraction</strong>: Beinhaltet die zentrale Schnittstellenkomponente <code>Memory Hardware Abstraction::Memory Abstraction Interface</code> (MemIf) sowie die beiden Abstraktionsmodule <code>Memory Hardware Abstraction::Flash EEPROM Emulation</code> (Fee) und <code>Memory Hardware Abstraction::EEPROM Abstraction</code> (Ea).</li>\n<li><strong>Memory Drivers</strong>: Hardwarenahe Treiberkomponenten, gegliedert in <code>Memory Drivers::Flash Driver</code> (Fls), <code>Memory Drivers::Vendor Specific Library</code> und <code>Memory Drivers::EEPROM Driver</code> (Eep).</li>\n</ul>\n<p class=\"fig-p\">Schnittstellenverbindungen (Ball-and-Socket / Assembly Connectors):</p>\n<ul class=\"fig-list\">\n<li><code>NVRAM Manager</code> nutzt (Socket) die von <code>Memory Abstraction Interface</code> bereitgestellte Schnittstelle (Ball).</li>\n<li><code>Memory Abstraction Interface</code> delegiert nach unten: nutzt über Socket-Ball-Verbindungen die angebotenen Schnittstellen von <code>Flash EEPROM Emulation</code> und <code>EEPROM Abstraction</code>.</li>\n<li>Zudem besteht eine vertikale Verbindung von <code>Memory Abstraction Interface</code> direkt zur <code>Vendor Specific Library</code> über einen Socket-Ball-Konnektor.</li>\n<li><code>Flash EEPROM Emulation</code> nutzt über eine Socket-Ball-Verbindung die Schnittstelle des darunterliegenden <code>Flash Driver</code>.</li>\n<li><code>EEPROM Abstraction</code> nutzt über eine Socket-Ball-Verbindung die Schnittstelle des darunterliegenden <code>EEPROM Driver</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Architekturübersicht ohne explizite Interaktionssequenzen oder Kontrollflusspfeile. Die Aufrufhierarchie verläuft top-down:</p>\n<ol class=\"fig-list\">\n<li>Der NVRAM Manager greift über das Memory Abstraction Interface (MemIf) auf den nichtflüchtigen Speicher zu.</li>\n<li>Das MemIf leitet die Zugriffe bausteinspezifisch an die Flash EEPROM Emulation (Fee) oder an die EEPROM Abstraction (Ea) bzw. alternativ an eine herstellerspezifische Bibliothek weiter.</li>\n<li>Die Flash EEPROM Emulation bedient sich des Flash Drivers zur hardwarenahen Ansteuerung des Flash-Speichers; die EEPROM Abstraction greift korrespondierend auf den EEPROM Driver zu.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architektonisch verbindliche Schichtung des AUTOSAR Memory Stacks gemäß SWS Flash EEPROM Emulation:</p>\n<ul class=\"fig-list\">\n<li>Die Flash EEPROM Emulation emuliert ein EEPROM-Verhalten auf Flash-Speicher und darf ausschließlich über das Memory Abstraction Interface (MemIf) von oberen Schichten adressiert werden.</li>\n<li>Unterhalb der Fee ist die Anbindung an den Fls-Treiber verbindlich vorgegeben.</li>\n<li>Das Diagramm dokumentiert die Kapselung der hardwareabhängigen Flash- und EEPROM-Treiber gegenüber dem NVRAM Manager durch die Memory Hardware Abstraction Layer.</li>\n</ul>"}, {"id": "FIG-f57ab1a2f9864348", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm (<code>Component Model</code>) zur Einordnung der Speichermodule in die AUTOSAR-Basissoftwarearchitektur. Das Diagramm zeigt die Schichtenstruktur des Speichersubsystems (Memory Stack) bestehend aus den drei Paketen bzw. Modulschichten <code>NVRAM Manager</code> (Services Layer), <code>Memory Hardware Abstraction</code> (ECU Abstraction Layer) und <code>Memory Drivers</code> (Microcontroller Abstraction Layer / MCAL bzw. Complex Drivers).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in drei Hauptpakete:</p>\n<ul class=\"fig-list\">\n<li><strong>NVRAM Manager</strong>: Übergeordnete Service-Komponente zur Verwaltung nichtflüchtiger Daten.</li>\n<li><strong>Memory Hardware Abstraction</strong>: Beinhaltet die zentrale Schnittstellenkomponente <code>Memory Hardware Abstraction::Memory Abstraction Interface</code> (MemIf) sowie die beiden Abstraktionsmodule <code>Memory Hardware Abstraction::Flash EEPROM Emulation</code> (Fee) und <code>Memory Hardware Abstraction::EEPROM Abstraction</code> (Ea).</li>\n<li><strong>Memory Drivers</strong>: Hardwarenahe Treiberkomponenten, gegliedert in <code>Memory Drivers::Flash Driver</code> (Fls), <code>Memory Drivers::Vendor Specific Library</code> und <code>Memory Drivers::EEPROM Driver</code> (Eep).</li>\n</ul>\n<p class=\"fig-p\">Schnittstellenverbindungen (Ball-and-Socket / Assembly Connectors):</p>\n<ul class=\"fig-list\">\n<li><code>NVRAM Manager</code> nutzt (Socket) die von <code>Memory Abstraction Interface</code> bereitgestellte Schnittstelle (Ball).</li>\n<li><code>Memory Abstraction Interface</code> delegiert nach unten: nutzt über Socket-Ball-Verbindungen die angebotenen Schnittstellen von <code>Flash EEPROM Emulation</code> und <code>EEPROM Abstraction</code>.</li>\n<li>Zudem besteht eine vertikale Verbindung von <code>Memory Abstraction Interface</code> direkt zur <code>Vendor Specific Library</code> über einen Socket-Ball-Konnektor.</li>\n<li><code>Flash EEPROM Emulation</code> nutzt über eine Socket-Ball-Verbindung die Schnittstelle des darunterliegenden <code>Flash Driver</code>.</li>\n<li><code>EEPROM Abstraction</code> nutzt über eine Socket-Ball-Verbindung die Schnittstelle des darunterliegenden <code>EEPROM Driver</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Architekturübersicht ohne explizite Interaktionssequenzen oder Kontrollflusspfeile. Die Aufrufhierarchie verläuft top-down:</p>\n<ol class=\"fig-list\">\n<li>Der NVRAM Manager greift über das Memory Abstraction Interface (MemIf) auf den nichtflüchtigen Speicher zu.</li>\n<li>Das MemIf leitet die Zugriffe bausteinspezifisch an die Flash EEPROM Emulation (Fee) oder an die EEPROM Abstraction (Ea) bzw. alternativ an eine herstellerspezifische Bibliothek weiter.</li>\n<li>Die Flash EEPROM Emulation bedient sich des Flash Drivers zur hardwarenahen Ansteuerung des Flash-Speichers; die EEPROM Abstraction greift korrespondierend auf den EEPROM Driver zu.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architektonisch verbindliche Schichtung des AUTOSAR Memory Stacks gemäß SWS Flash EEPROM Emulation:</p>\n<ul class=\"fig-list\">\n<li>Die Flash EEPROM Emulation emuliert ein EEPROM-Verhalten auf Flash-Speicher und darf ausschließlich über das Memory Abstraction Interface (MemIf) von oberen Schichten adressiert werden.</li>\n<li>Unterhalb der Fee ist die Anbindung an den Fls-Treiber verbindlich vorgegeben.</li>\n<li>Das Diagramm dokumentiert die Kapselung der hardwareabhängigen Flash- und EEPROM-Treiber gegenüber dem NVRAM Manager durch die Memory Hardware Abstraction Layer.</li>\n</ul>"}, {"id": "FIG-71c31114717c9040", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm (<code>Component Model</code>) zur Einordnung der Speichermodule in die AUTOSAR-Basissoftwarearchitektur. Das Diagramm zeigt die Schichtenstruktur des Speichersubsystems (Memory Stack) bestehend aus den drei Paketen bzw. Modulschichten <code>NVRAM Manager</code> (Services Layer), <code>Memory Hardware Abstraction</code> (ECU Abstraction Layer) und <code>Memory Drivers</code> (Microcontroller Abstraction Layer / MCAL bzw. Complex Drivers).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in drei Hauptpakete:</p>\n<ul class=\"fig-list\">\n<li><strong>NVRAM Manager</strong>: Übergeordnete Service-Komponente zur Verwaltung nichtflüchtiger Daten.</li>\n<li><strong>Memory Hardware Abstraction</strong>: Beinhaltet die zentrale Schnittstellenkomponente <code>Memory Hardware Abstraction::Memory Abstraction Interface</code> (MemIf) sowie die beiden Abstraktionsmodule <code>Memory Hardware Abstraction::Flash EEPROM Emulation</code> (Fee) und <code>Memory Hardware Abstraction::EEPROM Abstraction</code> (Ea).</li>\n<li><strong>Memory Drivers</strong>: Hardwarenahe Treiberkomponenten, gegliedert in <code>Memory Drivers::Flash Driver</code> (Fls), <code>Memory Drivers::Vendor Specific Library</code> und <code>Memory Drivers::EEPROM Driver</code> (Eep).</li>\n</ul>\n<p class=\"fig-p\">Schnittstellenverbindungen (Ball-and-Socket / Assembly Connectors):</p>\n<ul class=\"fig-list\">\n<li><code>NVRAM Manager</code> nutzt (Socket) die von <code>Memory Abstraction Interface</code> bereitgestellte Schnittstelle (Ball).</li>\n<li><code>Memory Abstraction Interface</code> delegiert nach unten: nutzt über Socket-Ball-Verbindungen die angebotenen Schnittstellen von <code>Flash EEPROM Emulation</code> und <code>EEPROM Abstraction</code>.</li>\n<li>Zudem besteht eine vertikale Verbindung von <code>Memory Abstraction Interface</code> direkt zur <code>Vendor Specific Library</code> über einen Socket-Ball-Konnektor.</li>\n<li><code>Flash EEPROM Emulation</code> nutzt über eine Socket-Ball-Verbindung die Schnittstelle des darunterliegenden <code>Flash Driver</code>.</li>\n<li><code>EEPROM Abstraction</code> nutzt über eine Socket-Ball-Verbindung die Schnittstelle des darunterliegenden <code>EEPROM Driver</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Architekturübersicht ohne explizite Interaktionssequenzen oder Kontrollflusspfeile. Die Aufrufhierarchie verläuft top-down:</p>\n<ol class=\"fig-list\">\n<li>Der NVRAM Manager greift über das Memory Abstraction Interface (MemIf) auf den nichtflüchtigen Speicher zu.</li>\n<li>Das MemIf leitet die Zugriffe bausteinspezifisch an die Flash EEPROM Emulation (Fee) oder an die EEPROM Abstraction (Ea) bzw. alternativ an eine herstellerspezifische Bibliothek weiter.</li>\n<li>Die Flash EEPROM Emulation bedient sich des Flash Drivers zur hardwarenahen Ansteuerung des Flash-Speichers; die EEPROM Abstraction greift korrespondierend auf den EEPROM Driver zu.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architektonisch verbindliche Schichtung des AUTOSAR Memory Stacks gemäß SWS Flash EEPROM Emulation:</p>\n<ul class=\"fig-list\">\n<li>Die Flash EEPROM Emulation emuliert ein EEPROM-Verhalten auf Flash-Speicher und darf ausschließlich über das Memory Abstraction Interface (MemIf) von oberen Schichten adressiert werden.</li>\n<li>Unterhalb der Fee ist die Anbindung an den Fls-Treiber verbindlich vorgegeben.</li>\n<li>Das Diagramm dokumentiert die Kapselung der hardwareabhängigen Flash- und EEPROM-Treiber gegenüber dem NVRAM Manager durch die Memory Hardware Abstraction Layer.</li>\n</ul>"}], "trans": [{"from": "FIG-584d2e8102693d79", "to": "FIG-f57ab1a2f9864348", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-f57ab1a2f9864348", "to": "FIG-71c31114717c9040", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
